import math

def label_stats(rows):
    by = {}
    for label, ms, ok in rows:
        by.setdefault(label, []).append((ms, ok))
    out = {}
    for label, items in by.items():
        times = sorted(ms for ms, _ in items)
        n = len(times)
        def pct(p):
            return times[max(0, math.ceil(p / 100 * n) - 1)]
        errors = sum(1 for _, ok in items if not ok)
        out[label] = {"samples": n, "p90": pct(90), "p95": pct(95), "error_pct": round(errors * 100 / n, 2)}
    return out

